from dataclasses import dataclass

from lib.catalog.rates import rate_for


@dataclass(frozen=True)
class InvoiceLine:
    description: str
    amount_cents: int


def invoice_amount_cents(plan: str, seats: int) -> int:
    if seats < 1:
        raise ValueError("seats must be positive")
    return int(rate_for(plan) * seats * 100)


def invoice_line(plan: str, seats: int) -> InvoiceLine:
    return InvoiceLine(f"{plan} plan, {seats} seats", invoice_amount_cents(plan, seats))
